public M3TMModelManager getModelManager() {
    checkInitialized();
    return modelManager;
}

public M3TMTrainingManager getTrainingManager() {
    checkInitialized();
    return trainingManager;
}

public interface TrainingCallback {
    void onBatchComplete(int batch, Map<String, Object> metrics);
    void onEpochComplete(int epoch, Map<String, Object> metrics);
    void onTrainingComplete(Map<String, Object> metrics);
}

public synchronized void close() {
    if (nativeHandle != 0) {
        // Tüm yüklü modelleri kapat
        for (M3TMModel model : loadedModels.values()) {
            if (!model.isClosed()) {
                model.close();
            }
        }
        loadedModels.clear();

        // Native ModelManager'ı kapat
        nativeClose(nativeHandle);
        nativeHandle = 0;
    }
}

@Override
protected void finalize() throws Throwable {
    try {
        close();
    } finally {
        super.finalize();
    }
}

